(()=>{
 const $=id=>document.getElementById(id);let selected='top',items={},saved=[],editing=null,scene=null,loadingScene=false,owner=null,importGeneration=0;
 function message(text){$('outfitSaveStatus').textContent=text}
 function form(){document.querySelectorAll('[data-slot]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.slot===selected)));$('outfitShape').replaceChildren();OUTFIT_SHAPES[selected].forEach(shape=>{const option=new Option(OUTFIT_LABELS[shape],shape);$('outfitShape').append(option)});const x=items[selected]||{};$('outfitShape').value=x.shape||OUTFIT_SHAPES[selected][0];$('outfitColor').value=x.color||'#e9dfcf';$('outfitTitle').value=x.title||'';$('outfitUrl').value=x.url||'';$('outfitImage').value=x.image||'';$('outfitWish').value='';$('outfitImportStatus').textContent='';}
 document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{selected=b.dataset.slot;importGeneration++;form()});
 function render(){scene?.update(items);$('outfitReferences').replaceChildren();for(const [slot,x] of Object.entries(items)){const card=document.createElement('article');if(x.image){const img=document.createElement('img');img.src=x.image;img.alt=x.title||OUTFIT_LABELS[x.shape];img.loading='lazy';img.referrerPolicy='no-referrer';img.onerror=()=>img.remove();card.append(img)}const title=document.createElement('h3');title.textContent=x.title||OUTFIT_LABELS[x.shape];card.append(title);if(x.url){const link=document.createElement('a');link.href=x.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Vedi il capo reale ↗';card.append(link)}const swatch=document.createElement('span');swatch.className='outfit-swatch';swatch.style.background=x.color;card.append(swatch);$('outfitReferences').append(card)}}
 async function mount(){if(scene||loadingScene)return;loadingScene=true;try{const m=await import('./outfit-scene.js');scene=m.mountOutfit($('outfitCanvas'),items);$('outfit3dStatus').hidden=!!scene;for(const id of ['outfitLeft','outfitRight','outfitFront'])$(id).disabled=!scene;if(!scene)$('outfit3dStatus').textContent='Il 3D non è disponibile su questo browser. Puoi comunque comporre e salvare i capi qui sotto.'}catch{$('outfit3dStatus').textContent='Impossibile caricare il 3D. Riapri questa sezione per riprovare.'}finally{loadingScene=false}}
 $('outfitCanvas').addEventListener('outfit:textures',e=>{const d=e.detail;$('outfitTextureStatus').textContent=d.loading?'Caricamento delle foto sul manichino…':d.failed?'Alcune immagini sono bloccate dal negozio. Per quei capi resta il colore scelto; prova un altro URL immagine.':d.loaded?'Foto applicate alle sagome: proporzioni, stampe e vestibilità sono indicative.':'Aggiungi una foto del prodotto per usarla sulla sagoma.';});
 $('outfitLeft').onclick=()=>scene?.rotate(-Math.PI/6);$('outfitRight').onclick=()=>scene?.rotate(Math.PI/6);$('outfitFront').onclick=()=>scene?.front();
 $('outfitForm').onsubmit=e=>{e.preventDefault();if(!$('outfitTitle').value.trim()){ $('outfitTitle').focus();$('outfitImportStatus').textContent='Dai un nome al capo prima di applicarlo.';return}items=cleanOutfitItems({...items,[selected]:{shape:$('outfitShape').value,color:$('outfitColor').value,title:$('outfitTitle').value.trim(),url:$('outfitUrl').value.trim(),image:$('outfitImage').value.trim()}});render();message('Anteprima aggiornata. Salva l’outfit per ritrovarlo nel tuo account.');};
 $('outfitRemove').onclick=()=>{delete items[selected];form();render()};
 $('outfitImport').onclick=async()=>{const url=outfitWebUrl($('outfitUrl').value.trim());if(!url){$('outfitImportStatus').textContent='Inserisci un link completo http:// o https://.';return}const generation=++importGeneration,account=owner;const button=$('outfitImport');button.disabled=true;$('outfitImportStatus').textContent='Lettura del prodotto…';try{const res=await fetch('/api/fetch-product',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url}),signal:AbortSignal.timeout(15000)});const data=await res.json();if(generation!==importGeneration||account!==owner)return;if(!res.ok)throw Error();if(data.title)$('outfitTitle').value=String(data.title).slice(0,100);if(outfitWebUrl(data.image))$('outfitImage').value=outfitWebUrl(data.image);$('outfitImportStatus').textContent='Controlla i dettagli, scegli forma e colore e premi Applica.'}catch{if(generation===importGeneration&&account===owner)$('outfitImportStatus').textContent='Il negozio non consente la lettura automatica. Compila nome e foto manualmente: il link resta disponibile.'}finally{button.disabled=false}};
 $('outfitWish').onchange=()=>{const x=wishlistEntries.find(x=>x.id===$('outfitWish').value);if(!x)return;$('outfitTitle').value=x.title||'';$('outfitUrl').value=outfitWebUrl(x.product_url);$('outfitImage').value=outfitWebUrl(x.image_url);$('outfitImportStatus').textContent='Prodotto selezionato. Scegli forma e colore e premi Applica.'};
 function refreshWishlist(){const previous=$('outfitWish').value;$('outfitWish').replaceChildren(new Option('Seleziona un prodotto',''));for(const x of wishlistEntries)$('outfitWish').append(new Option(x.title,x.id));$('outfitWish').value=previous}
 function renderSaved(){$('outfitSaved').replaceChildren();if(!saved.length){$('outfitSaved').textContent='Il tuo primo outfit inizia dai capi che ti piacciono.';return}for(const look of saved){const card=document.createElement('article');const title=document.createElement('h3');title.textContent=look.name;card.append(title);const swatches=document.createElement('div');for(const x of Object.values(look.items)){const swatch=document.createElement('span');swatch.className='outfit-swatch';swatch.style.background=x.color;swatches.append(swatch)}card.append(swatches);const open=document.createElement('button');open.type='button';open.textContent='Apri outfit ↗';open.onclick=()=>{editing=look.id;items=cleanOutfitItems(look.items);$('outfitName').value=look.name;form();render();$('outfitCanvas').scrollIntoView({block:'center',behavior:'auto'})};const remove=document.createElement('button');remove.type='button';remove.textContent='Elimina';remove.onclick=async()=>{if(!confirm('Eliminare questo outfit salvato?'))return;remove.disabled=true;try{await persist(saved.filter(x=>x.id!==look.id));if(editing===look.id)editing=null}catch(e){message(e.message)}finally{remove.disabled=false}};card.append(open,remove);$('outfitSaved').append(card)}}
 let saving=false;
 async function persist(next){if(saving)throw Error('Attendi il salvataggio in corso.');saving=true;const account=owner;try{const user=await getCurrentUser();if(!account||user?.id!==account)throw Error('Accedi di nuovo per salvare.');const response=await authorizedFetch(`${AUTH_ENDPOINT}/user`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({data:{saved_outfits:cleanSavedOutfits(next)}})});const updated=await response.json();if(!response.ok)throw Error(updated.message||updated.msg||'Salvataggio non riuscito.');if(owner!==account||currentUser?.id!==account)throw Error('L’account è cambiato.');currentUser=updated;saved=cleanSavedOutfits(updated.user_metadata?.saved_outfits);renderSaved();message('Salvato nel tuo account.')}finally{saving=false}}
 $('outfitSave').onclick=async()=>{if(!Object.keys(items).length){message('Applica almeno un capo al manichino.');return}const name=$('outfitName').value.trim();if(!name){message('Dai un nome al tuo outfit.');$('outfitName').focus();return}if(!editing&&saved.length>=12){message('Hai 12 outfit: modifica o elimina una combinazione prima di aggiungerne un’altra.');return}const id=editing||crypto.randomUUID(),look={id,name,items:cleanOutfitItems(items)};const next=editing?saved.map(x=>x.id===id?look:x):[look,...saved];$('outfitSave').disabled=true;try{await persist(next);editing=id}catch(e){message(e.message)}finally{$('outfitSave').disabled=false}};
 $('outfitNew').onclick=()=>{editing=null;items={};$('outfitName').value='';form();render();message('Nuova combinazione. Nessun outfit salvato è stato eliminato.')};
 function sync(){const user=typeof currentUser!=='undefined'?currentUser:null;if(owner!==user?.id){owner=user?.id||null;items={};editing=null;importGeneration++;$('outfitName').value='';form();render();message('')}saved=cleanSavedOutfits(user?.user_metadata?.saved_outfits);renderSaved()}
 addEventListener('workspace:open-outfit',e=>{const look=saved.find(x=>x.id===e.detail);if(!look)return;editing=look.id;items=cleanOutfitItems(look.items);$('outfitName').value=look.name;form();render();});
 addEventListener('workspace:module',e=>{if(e.detail==='outfit'){sync();refreshWishlist();mount()}});addEventListener('personal:appearance',sync);new MutationObserver(()=>{if(!$('authOverlay').classList.contains('hidden')){owner=null;items={};saved=[];editing=null;importGeneration++;$('outfitName').value='';form();render();renderSaved();message('')}}).observe($('authOverlay'),{attributes:true,attributeFilter:['class']});addEventListener('pagehide',e=>{if(!e.persisted){scene?.dispose();scene=null}});form();
})();
